import os
import base64
import uuid
import urllib.parse
from pathlib import Path

import requests
from fastapi import FastAPI, HTTPException, Request
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

app = FastAPI()

# Folder for images generated by providers that return raw bytes (e.g. Cloudflare)
IMAGES_DIR = Path("generated_images")
IMAGES_DIR.mkdir(exist_ok=True)
app.mount("/images", StaticFiles(directory=str(IMAGES_DIR)), name="images")

class ImageRequest(BaseModel):
    prompt: str

# 1. Segmind Image Generation Function (Primary)
def generate_with_segmind(prompt: str):
    # Sahi tareeqa: Environment variable ka naam likhna hai
    api_key = os.environ.get("SEGMIND_API_KEY")
    if not api_key:
        raise Exception("Segmind API key not found in environment variables")
    
    url = "https://api.segmind.com/v1/sdxl-1.0-base"
    payload = {
        "prompt": prompt,
        "samples": 1,
        "scheduler": "euler_a",
        "num_inference_steps": 25,
        "guidance_scale": 7.5,
        "img_width": 512,
        "img_height": 512,
        "base64": False
    }
    headers = {"x-api-key": api_key}
    
    response = requests.post(url, json=payload, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Segmind failed with status {response.status_code}: {response.text}")

# 2. Runware Image Generation Function (Secondary)
def generate_with_runware(prompt: str):
    # Sahi tareeqa: Environment variable ka naam likhna hai
    api_key = os.environ.get("RUNWARE_API_KEY")
    if not api_key:
        raise Exception("Runware API key not found in environment variables")
    
    url = "https://api.runware.ai/v1"
    headers = {"Authorization": f"Bearer {api_key}"}
    payload = [
        {
            "taskType": "imageInference",
            "taskUUID": "unique-task-id",
            "positivePrompt": prompt,
            "model": "runware:100@1",
            "width": 512,
            "height": 512,
            "numberResults": 1,
            "outputType": "URL"
        }
    ]
    
    response = requests.post(url, json=payload, headers=headers)
    if response.status_code == 200:
        data = response.json()
        image_url = data['data'][0]['imageURL']
        return {"image_url": image_url}
    else:
        raise Exception(f"Runware failed with status {response.status_code}: {response.text}")

# 3. Pollinations.ai Image Generation Function (Third Fallback - Free & Open)
def generate_with_pollinations(prompt: str):
    encoded_prompt = urllib.parse.quote(prompt)
    image_url = f"https://image.pollinations.ai/prompt/{encoded_prompt}"
    
    response = requests.get(image_url)
    if response.status_code == 200:
        return {"image_url": image_url}
    else:
        raise Exception(f"Pollinations failed with status {response.status_code}")

# 4. Cloudflare Workers AI (Free tier: 10,000 Neurons/day, no credit card)
def generate_with_cloudflare(prompt: str, base_url: str):
    account_id = os.environ.get("CF_ACCOUNT_ID")
    api_token = os.environ.get("CF_API_TOKEN")
    if not account_id or not api_token:
        raise Exception("Cloudflare credentials (CF_ACCOUNT_ID / CF_API_TOKEN) not set")

    url = (
        f"https://api.cloudflare.com/client/v4/accounts/{account_id}"
        "/ai/run/@cf/black-forest-labs/flux-1-schnell"
    )
    headers = {"Authorization": f"Bearer {api_token}", "Content-Type": "application/json"}
    payload = {"prompt": prompt, "steps": 4}

    response = requests.post(url, json=payload, headers=headers, timeout=90)
    if response.status_code != 200:
        raise Exception(f"Cloudflare failed with status {response.status_code}: {response.text}")

    image_b64 = response.json()["result"]["image"]
    filename = f"cf_{uuid.uuid4().hex}.jpg"
    (IMAGES_DIR / filename).write_bytes(base64.b64decode(image_b64))
    return {"image_url": f"{base_url.rstrip('/')}/images/{filename}"}


# Main Multi-API Fallback Endpoint
@app.post("/generate-image")
def generate_image(data: ImageRequest, request: Request):
    prompt = data.prompt
    base_url = str(request.base_url)
    # Render terminates TLS at the proxy; make sure we hand the app an https URL
    if request.headers.get("x-forwarded-proto") == "https":
        base_url = base_url.replace("http://", "https://", 1)
    
    # Try 1: Segmind
    try:
        print("Trying Segmind (Primary)...")
        result = generate_with_segmind(prompt)
        return {"provider": "segmind", "result": result}
    except Exception as e:
        print(f"Segmind error/exhausted: {e}")
        
    # Try 2: Runware
    try:
        print("Fallback to Runware (Secondary)...")
        result = generate_with_runware(prompt)
        return {"provider": "runware", "result": result}
    except Exception as e:
        print(f"Runware error: {e}")

    # Try 3: Cloudflare Workers AI (free)
    try:
        print("Fallback to Cloudflare Workers AI (Free)...")
        result = generate_with_cloudflare(prompt, base_url)
        return {"provider": "cloudflare", "result": result}
    except Exception as e:
        print(f"Cloudflare error: {e}")

    # Try 4: Pollinations.ai (keyless but heavily rate-limited)
    try:
        print("Trying Pollinations.ai (Last)...")
        result = generate_with_pollinations(prompt)
        return {"provider": "pollinations", "result": result}
    except Exception as e:
        print(f"Pollinations error: {e}")

    raise HTTPException(status_code=500, detail="All image generation providers are currently unavailable.")

@app.get("/debug")
def debug():
    cid = bool(os.environ.get("CF_ACCOUNT_ID"))
    tok = os.environ.get("CF_API_TOKEN")
    verify = None
    if tok:
        try:
            r = requests.get(
                "https://api.cloudflare.com/client/v4/user/tokens/verify",
                headers={"Authorization": f"Bearer {tok}"},
                timeout=15,
            )
            verify = r.status_code
        except Exception as e:
            verify = f"error: {e}"
    return {
        "CF_ACCOUNT_ID_set": cid,
        "CF_API_TOKEN_set": bool(tok),
        "token_verify": verify,
    }

@app.get("/")
def home():
    return {"message": "Welcome to ManifestAI Backend with 4-Layer Multi-API Fallback ✨ (Segmind → Runware → Cloudflare → Pollinations)"}